-- Direct origin identity verified against repeated catalog, eight observed episodes,
-- matching watch page and an existing allowed player returning MP4 HEAD 200.
-- No new media hosts or redirect exceptions are admitted.
insert into public.najd_provider_config(provider,enabled,config) values('laroza',true,'{"primary_domain":"https://laroza1.site"}'::jsonb) on conflict(provider) do update set enabled=true,config=jsonb_set(najd_provider_config.config,'{primary_domain}','"https://laroza1.site"'::jsonb),revision=najd_provider_config.revision+1,updated_at=now() where not najd_provider_config.enabled or najd_provider_config.config->>'primary_domain' is distinct from 'https://laroza1.site';
insert into public.najd_beta_provider_config(provider,enabled,config) values('laroza',true,'{"primary_domain":"https://laroza1.site"}'::jsonb) on conflict(provider) do update set enabled=true,config=jsonb_set(najd_beta_provider_config.config,'{primary_domain}','"https://laroza1.site"'::jsonb),revision=najd_beta_provider_config.revision+1,updated_at=now() where not najd_beta_provider_config.enabled or najd_beta_provider_config.config->>'primary_domain' is distinct from 'https://laroza1.site';
